import { useEffect, useReducer } from 'react'
import { ArtScene } from './ArtScene.tsx'
import { artTransition } from './transition.ts'
import type { Artwork } from './catalog.ts'

/** Decoding and dissolving are separate: a slow or failed image never erases the last scene. */
export function ArtBackdrop({ artwork, still, retry = 0, onReady, onFailure }: { artwork: Artwork; still: boolean; retry?: number; onReady?: (id: string) => void; onFailure?: (id: string) => void }) {
  const [state, dispatch] = useReducer(artTransition, { base: artwork, incoming: null, ready: false })
  useEffect(() => { dispatch({ type: 'request', artwork }) }, [artwork, retry])
  useEffect(() => {
    if (!state.ready || !state.incoming) return
    const id = state.incoming.id
    const timer = setTimeout(() => dispatch({ type: 'settle', id }), 2400)
    return () => clearTimeout(timer)
  }, [state.ready, state.incoming])
  return <>{[state.base, ...(state.incoming ? [state.incoming] : [])].map(layer => <ArtScene key={`${layer.id}:${retry}`} artwork={layer} still={still}
    onReady={() => { dispatch({ type: 'ready', id: layer.id }); onReady?.(layer.id) }}
    onFailure={() => { dispatch({ type: 'failed', id: layer.id }); onFailure?.(layer.id) }} />)}</>
}

import { useEffect, useRef, useState } from 'react'
import { animate } from 'motion/mini'
import { artworkUrl, type Artwork } from './catalog.ts'

/** SVGs are isolated image resources, never injected into the document. */
export function ArtScene({ artwork, still, className = '', onReady, onFailure }: { artwork: Artwork; still: boolean; className?: string; onReady?: () => void; onFailure?: () => void }) {
  const [loaded, setLoaded] = useState(false)
  const image = useRef<HTMLImageElement>(null)
  const camera = useRef<ReturnType<typeof animate> | null>(null)
  useEffect(() => {
    const element = image.current
    if (!element || !loaded) return
    const movement = animate(element, { transform: ['scale(1.015) translateX(0%)', 'scale(1.08) translateX(-1.2%)'] }, { duration: 80, repeat: Infinity, repeatType: 'reverse', ease: 'easeInOut' })
    camera.current = movement
    if (still) movement.pause()
    return () => { movement.stop(); camera.current = null }
  }, [loaded])
  useEffect(() => { if (still) camera.current?.pause(); else camera.current?.play() }, [still])
  return <div className={`art-scene ${className}${loaded ? ' is-ready' : ''}`} data-artwork={artwork.id} data-still={still}>
    <img ref={image} src={artworkUrl(artwork)} alt="" width="1600" height="1000" decoding="async" onLoad={() => { setLoaded(true); onReady?.() }} onError={() => { setLoaded(false); onFailure?.() }} />
  </div>
}

import { useEffect, useRef, useState } from 'react'
import { ARTWORKS, type Artwork } from './catalog.ts'
import { ArtBackdrop } from './ArtBackdrop.tsx'
import { usePrefersReducedMotion } from '../hooks/usePrefersReducedMotion.ts'
import { useDocumentVisible } from '../hooks/useDocumentVisible.ts'

export function ArtViewer({ artwork, onClose }: { artwork: Artwork; onClose: () => void }) {
  const dialog = useRef<HTMLDialogElement>(null)
  const [selected, setSelected] = useState(artwork)
  const reduced = usePrefersReducedMotion()
  const visible = useDocumentVisible()
  const [paused, setPaused] = useState(false)
  const [playing, setPlaying] = useState(false)
  const [idle, setIdle] = useState(false)
  const [failed, setFailed] = useState<string | null>(null)
  const [loaded, setLoaded] = useState<string | null>(null)
  const [retry, setRetry] = useState(0)
  const idleTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const elapsed = useRef(0)
  const index = ARTWORKS.findIndex(art => art.id === selected.id)
  const choose = (art: Artwork) => { elapsed.current = 0; setSelected(art); setFailed(null) }
  const move = (direction: number) => choose(ARTWORKS[(index + direction + ARTWORKS.length) % ARTWORKS.length]!)
  const reveal = () => {
    setIdle(false)
    if (idleTimer.current) clearTimeout(idleTimer.current)
    if (playing) idleTimer.current = setTimeout(() => setIdle(true), 6000)
  }
  useEffect(() => {
    const element = dialog.current
    element?.showModal()
    return () => element?.close()
  }, [])
  useEffect(() => {
    setIdle(false)
    if (playing) idleTimer.current = setTimeout(() => setIdle(true), 6000)
    return () => { if (idleTimer.current) clearTimeout(idleTimer.current) }
  }, [playing])
  useEffect(() => {
    if (!playing || paused || !visible || failed || loaded !== selected.id) return
    let previous = Date.now()
    const timer = setInterval(() => {
      const now = Date.now()
      elapsed.current += Math.max(0, now - previous)
      previous = now
      if (elapsed.current >= 60000) {
        elapsed.current = 0
        setSelected(current => ARTWORKS[(ARTWORKS.findIndex(art => art.id === current.id) + 1) % ARTWORKS.length]!)
      }
    }, 250)
    return () => clearInterval(timer)
  }, [playing, paused, visible, failed, loaded, selected.id])
  return <dialog className={`art-viewer${playing ? ' is-playing' : ''}${idle ? ' is-idle' : ''}`} ref={dialog} aria-labelledby="art-title" onCancel={onClose} onClose={onClose}
    onPointerMove={reveal} onPointerDown={reveal} onFocusCapture={reveal} onKeyDown={event => {
      reveal()
      if (event.target instanceof HTMLSelectElement) return
      if (event.key === 'ArrowRight') { event.preventDefault(); move(1) }
      if (event.key === 'ArrowLeft') { event.preventDefault(); move(-1) }
    }}>
    <div className="art-viewer-stage"><ArtBackdrop artwork={selected} still={reduced || paused || !visible} retry={retry}
      onReady={id => { if (id === selected.id) { setLoaded(id); setFailed(null) } }} onFailure={id => { if (id === selected.id) setFailed(id) }} /></div>
    <header><p>{selected.bookTitle} <span>· {String(index + 1).padStart(2, '0')} / 66</span></p><button type="button" onClick={onClose} autoFocus>Close artwork</button></header>
    {failed === selected.id && <div className="art-error" role="status"><p>This illustration couldn’t load.</p><button type="button" onClick={() => { setFailed(null); setRetry(value => value + 1) }}>Retry artwork</button><button type="button" onClick={() => move(1)}>Skip artwork</button></div>}
    <footer>
      <div className="art-viewer-caption"><p className="hero-kicker">{playing ? 'The collection · one minute at a time' : 'A visual meditation'}</p><h2 id="art-title">{selected.title}</h2></div>
      <div className="art-viewer-controls">
        <button type="button" onClick={() => move(-1)} aria-label="Previous artwork">Previous</button>
        <label><span className="sr-only">Choose a book artwork</span><select aria-label="Choose a book artwork" value={selected.id} onChange={event => choose(ARTWORKS.find(art => art.id === event.target.value)!)}>{ARTWORKS.map(art => <option value={art.id} key={art.id}>{art.bookTitle}</option>)}</select></label>
        <button type="button" onClick={() => move(1)} aria-label="Next artwork">Next</button>
        <button type="button" onClick={event => { setPlaying(value => !value); if (event.detail) event.currentTarget.blur() }} aria-pressed={playing}>{playing ? 'Stop collection' : 'Play collection'}</button>
        <button type="button" onClick={() => setPaused(value => !value)} aria-pressed={paused}>{paused ? 'Resume motion' : 'Pause motion'}</button>
      </div>
    </footer>
  </dialog>
}

import records from './catalog.json'
export const ARTWORKS = records
export type Artwork = typeof ARTWORKS[number]
export function artworkForPassage(reference: string): Artwork {
  const name = reference.replace(/\s+\d+:.*$/, '').toLowerCase().replaceAll(' ', '-')
  const id = name === 'psalm' ? 'psalms' : name
  return ARTWORKS.find(art => art.id === id) ?? ARTWORKS[0]!
}
export function artworkUrl(art: Artwork) { return `${import.meta.env.BASE_URL}art/scripture/${art.file}` }
